pub fn miya(ctx: &Ctx) -> Script {
    miya_run(ctx, MiyaStep::Start, Vec::new()).map(|_| ())
}

pub fn miya_ontouch(ctx: &Ctx) -> Script {
    miya_run(ctx, MiyaStep::OnTouch, Vec::new()).map(|_| ())
}

